mapper.select:
SELECT friend_id, member_id, friend_member_id, remark, deleted_flag, create_time, update_time
FROM t_friend
WHERE friend_id = #{friendId}
  AND deleted_flag = #{deletedFlag}

SELECT friend_id, member_id, friend_member_id, remark, deleted_flag, create_time, update_time
FROM t_friend
WHERE member_id = #{memberId}
  AND friend_member_id = #{friendMemberId}
  AND deleted_flag = #{deletedFlag}
LIMIT 1

SELECT friend_member_id
FROM t_friend
WHERE member_id = #{memberId}
  AND deleted_flag = #{deletedFlag}

SELECT COUNT(1)
FROM t_friend
WHERE member_id = #{memberId}
  AND deleted_flag = #{deletedFlag}

mapper.insert:
INSERT INTO t_friend (member_id, friend_member_id, remark, deleted_flag, create_time, update_time)
VALUES (#{memberId}, #{friendMemberId}, NULL, 0, #{now}, #{now})
ON DUPLICATE KEY UPDATE deleted_flag = 0, update_time = #{now}
